package com.reqlens.app;
import android.app.*;import android.graphics.Typeface;import android.os.Bundle;import android.util.Base64;import android.widget.*;import org.json.*;import java.net.*;import java.nio.charset.StandardCharsets;
public final class DecoderActivity extends Activity{
 private EditText in,out;@Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(16,16,16,16);TextView t=new TextView(this);t.setText("Decoder / Encoder");t.setTextSize(22);r.addView(t);in=new EditText(this);in.setHint("Input");in.setMinLines(5);in.setTypeface(Typeface.MONOSPACE);r.addView(in);LinearLayout a=new LinearLayout(this);String[]n={"URL ENCODE","URL DECODE","B64 ENCODE","B64 DECODE","JSON PRETTY","JSON MINIFY"};for(String x:n){Button bt=new Button(this);bt.setText(x);bt.setOnClickListener(v->go(((Button)v).getText().toString()));a.addView(bt,new LinearLayout.LayoutParams(0,50,1));}r.addView(a);out=new EditText(this);out.setHint("Output");out.setMinLines(8);out.setTextIsSelectable(true);out.setTypeface(Typeface.MONOSPACE);r.addView(out);Button swap=new Button(this);swap.setText("USE OUTPUT AS INPUT");swap.setOnClickListener(v->in.setText(out.getText().toString()));r.addView(swap);setContentView(r);}
 private void go(String m){try{String s=in.getText().toString(),z;if(m.equals("URL ENCODE"))z=URLEncoder.encode(s,"UTF-8");else if(m.equals("URL DECODE"))z=URLDecoder.decode(s,"UTF-8");else if(m.equals("B64 ENCODE"))z=Base64.encodeToString(s.getBytes(StandardCharsets.UTF_8),Base64.NO_WRAP);else if(m.equals("B64 DECODE"))z=new String(Base64.decode(s,Base64.DEFAULT),StandardCharsets.UTF_8);else if(m.equals("JSON PRETTY")){String q=s.trim();z=q.startsWith("[")?new JSONArray(q).toString(2):new JSONObject(q).toString(2);}else{String q=s.trim();z=q.startsWith("[")?new JSONArray(q).toString():new JSONObject(q).toString();}out.setText(z);}catch(Exception e){out.setText("Error: "+e.getMessage());}}
}
